### Module(s)

mini.completion

### Neovim version

0.11.x

### Description

When using mini.completion with mini.snippets, snippets are not proposed in markdown buffers with marksman LSP. They still trigger after a '#' character. I don't know if it is a mini.nvim bug or a marksman bug.

Here is my config relevant part : 

```
-- Mini Snippets
later(function()
	add({
		source = "rafamadriz/friendly-snippets",
	})

	local gen_loader = require("mini.snippets").gen_loader
	require("mini.snippets").setup({
		snippets = {
			-- Load custom file with global snippets first (adjust for Windows)
			gen_loader.from_file("~/.config/nvim/snippets/global.json"),

			-- Load snippets based on current language by reading files from
			-- "snippets/" subdirectories from 'runtimepath' directories.
			gen_loader.from_lang(),
		},
	})

	-- Integration with mini.completion
	---@diagnostic disable-next-line: undefined-global
	MiniSnippets.start_lsp_server({ match = false })
end)

-- Mini Completion
later(function()
	require("mini.completion").setup({
		lsp_completion = { source_func = "omnifunc", auto_setup = false },
	})

	if vim.fn.has("nvim-0.11") == 1 then
		vim.opt.completeopt:append("fuzzy") -- Use fuzzy matching for built-in completion
	end

	local on_attach = function(args)
		vim.bo[args.buf].omnifunc = "v:lua.MiniCompletion.completefunc_lsp"
	end
	vim.api.nvim_create_autocmd("LspAttach", { callback = on_attach })

	---@diagnostic disable-next-line: undefined-global
	vim.lsp.config("*", { capabilities = MiniCompletion.get_lsp_capabilities() })
end)
```


